using System;using System.Collections.ObjectModel;using System.ComponentModel;using System.IO;using System.Runtime.CompilerServices;using System.Threading;using System.Windows;using Autodesk.Revit.UI;using Microsoft.Win32;using SAUDICO.Federate.Core.Interfaces;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Core.Services;namespace SAUDICO.Federate.UI;
public partial class FederationManagerWindow:Window,INotifyPropertyChanged { readonly IRevitRequestQueue queue;readonly ExternalEvent externalEvent;CancellationTokenSource? cts;int index;string outputFolder="",logText="Ready.";bool overwrite;public ObservableCollection<FederationJob> Jobs{get;}=new();public string OutputFolder{get=>outputFolder;set{outputFolder=value;On();}}public string LogText{get=>logText;set{logText=value;On();}}public bool Overwrite{get=>overwrite;set{overwrite=value;On();}}public FederationManagerWindow(IRevitRequestQueue q,ExternalEvent e){InitializeComponent();queue=q;externalEvent=e;DataContext=this;}void AddRvt_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="Revit models (*.rvt)|*.rvt",Multiselect=true};if(d.ShowDialog()==true)foreach(var f in d.FileNames)try{Jobs.Add(new FederationJob{Model=new ModelInfo{FilePath=f,Type=ModelTypeDetector.Detect(f)}});}catch(Exception ex){Append(ex.Message);}}void AddAcc_Click(object s,RoutedEventArgs e){var d=new AccInputDialog{Owner=this};if(d.ShowDialog()==true&&d.Result!=null)Jobs.Add(new FederationJob{Model=d.Result});}void Remove_Click(object s,RoutedEventArgs e){if(JobsGrid.SelectedItem is FederationJob j)Jobs.Remove(j);}void Folder_Click(object s,RoutedEventArgs e){using var d=new System.Windows.Forms.FolderBrowserDialog();if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)OutputFolder=d.SelectedPath;}void Run_Click(object s,RoutedEventArgs e){if(Jobs.Count==0||!Directory.Exists(OutputFolder)){MessageBox.Show("Add models and select an output folder.");return;}cts=new CancellationTokenSource();index=0;QueueNext();}void Cancel_Click(object s,RoutedEventArgs e)=>cts?.Cancel();void QueueNext(){if(cts==null||cts.IsCancellationRequested||index>=Jobs.Count){Append("Batch finished.");return;}var j=Jobs[index];j.OutputDirectory=OutputFolder;j.Overwrite=Overwrite;queue.Enqueue(new RevitRequest(j,cts.Token,(x,m)=>Dispatcher.Invoke(()=>Append(x.Model.DisplayName+": "+m)),r=>Dispatcher.Invoke(()=>{j.OutputPath=r.Path;j.Error=r.Error;j.Status=r.Skipped?Shared.JobStatus.Skipped:r.Success?Shared.JobStatus.Succeeded:Shared.JobStatus.Failed;index++;QueueNext();}),ex=>Dispatcher.Invoke(()=>{j.Status=Shared.JobStatus.Failed;j.Error=ex.Message;index++;QueueNext();})));if(externalEvent.Raise()!=ExternalEventRequest.Accepted)Append("Revit rejected the ExternalEvent request.");}void Append(string t)=>LogText+=Environment.NewLine+DateTime.Now.ToString("HH:mm:ss")+"  "+t;public event PropertyChangedEventHandler? PropertyChanged;void On([CallerMemberName]string? n=null)=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(n)); }
